// Mengambil response body dalam bentuk JSON di Hoppscotch
var json = pw.response.body;

if (json && json.patient_ihs_id) {
    // Menyimpan nilai ke Environment Variable Hoppscotch
    pw.env.set('patient_ihs_id', json.patient_ihs_id);
    
    // Menampilkan log di console Hoppscotch
    console.log('Patient IHS ID saved to Environment:', json.patient_ihs_id);
}

